'use strict';

var Router = require('./core/Router');
var path = require('path');

module.exports = function (app) {
  if (process.env.NODE_ENV !== 'production') {
    app.get('/expressVisualizer/visualize', function (req, res, next) {
      // eslint-disable-line no-unused-vars
      res.sendFile(path.join(__dirname, './public/index.html'));
    });

    app.get('/expressVisualizer/fetchData', function (req, res, next) {
      // eslint-disable-line no-unused-vars
      res.json(new Router(app._router)); // eslint-disable-line no-underscore-dangle
    });

    app.get('/expressVisualizer/js/bundle.js', function (req, res, next) {
      // eslint-disable-line no-unused-vars
      res.sendFile(path.join(__dirname, './public/js/bundle.js'));
    });

    app.get('/expressVisualizer/js/bundle.js.map', function (req, res, next) {
      // eslint-disable-line no-unused-vars
      res.sendFile(path.join(__dirname, './public/js/bundle.js.map'));
    });
  }
};